from fractions import Fraction as Q
from math import factorial,comb
def moment(n,T):
 return Q(0) if n%4 else Q(factorial(n),factorial(n//4))*(-T)**(n//4)
def falling(n,r):return Q(0) if n<r else Q(factorial(n),factorial(n-r))
def integrated_mixed(k,l,T):
 if l<0:return Q(0)
 ans=Q(0)
 for a in range(l+1):
  if (k+a)%4 or (l-a)%4:continue
  A=(k+a)//4;B=(l-a)//4
  ans+=comb(l,a)*Q(factorial(k+a),factorial(A))*Q(factorial(l-a),factorial(B))*(-T)**(A+B)*Q(factorial(A)*factorial(B),factorial(A+B+1))
 return ans
checks=0;step_checks=0;examples=[]
for T in [Q(1),Q(1,2),Q(2),Q(5,7)]:
 for g in range(22):
  first=4*(-4*T)*falling(g,3)*integrated_mixed(3,g-3,T)
  second=6*(-12*T)*falling(g,2)*integrated_mixed(2,g-2,T)
  third=4*(-24*T)*falling(g,1)*integrated_mixed(1,g-1,T)
  drift=-24*T*moment(g,T)
  assert first+second+third+drift==moment(g+4,T)
  if T==1 and g in [0,4,8,12]:examples.append(dict(probe_degree=g,three_weighted_channels=[str(first),str(second),str(third)],drift=str(drift),actual_terminal_moment=str(moment(g+4,T))))
  checks+=1
  terms=[-24*T*moment(g,T)]
  for r,c in [(4,816*T*T),(8,-1152*T**3),(12,256*T**4)]:
   terms.append(Q(0) if g<r else c*falling(g,r)*moment(g-r,T))
  assert sum(terms)==moment(g+4,T)
  step_checks+=1
 assert moment(8,T)-moment(4,T)**2==19584*T*T
 assert 24*816==19584
print(dict(exact_four_channel_tests=checks,exact_fourth_step_expansion_tests=step_checks,passed=True,examples=examples,scope='Independent exact signed moments and time integrals; dual-norm results separately proved in Lean'))
